#pragma once
#include <cstdint>

#include <Geometry/MeshBuilder.hpp>

// Simple shapes as mesh sections (normals and UVs included, tangents generated by BuildMesh),
// centred on the origin with front faces outward.
namespace Primitives
{
    // A box with `size` edges; each face has its own vertices and the full UV range.
    MeshSection Cube(float size = 1.0f);
    // A flat square in the XZ plane facing +Y, split into `subdivisions` x `subdivisions` cells.
    MeshSection Plane(float size = 1.0f, uint32_t subdivisions = 1);
    // A UV sphere with `segments` around and `rings` from pole to pole.
    MeshSection Sphere(float radius = 0.5f, uint32_t segments = 32, uint32_t rings = 16);
}
